Create a reusable, high-performance table component that handles column head click triggers, dynamic sort direction state toggling, and clean visual indicator rendering (up/down arrow vectors):import { useState, useMemo } from "react";


interface Column {


  key: string;


  label: string;


  sortable?: boolean;


}


interface SortableTableProps {


  columns: Column[];


  data: any[];


  defaultSortKey?: string;


  renderRow: (item: any) => React.ReactNode;


}


export const SortableTable = ({ columns, data, defaultSortKey, renderRow }: SortableTableProps) => {


  const [sortConfig, setSortConfig] = useState<{ key: string; direction: "asc" | "desc" } | null>(


|---|    defaultSortKey ? { key: defaultSortKey, direction: "desc" } : null


  );


  const sortedData = useMemo(() => {


    if (!sortConfig) return data;





    const sorted = [...data].sort((a, b) => {


      const valA = a[sortConfig.key];


      const valB = b[sortConfig.key];


      if (valA === undefined || valB === undefined) return 0;


      if (typeof valA === "number" && typeof valB === "number") {


        return sortConfig.direction === "asc" ? valA - valB : valB - valA;


      }


      const strA = String(valA).toLowerCase();


      const strB = String(valB).toLowerCase();


      if (strA < strB) return sortConfig.direction === "asc" ? -1 : 1;


      if (strA > strB) return sortConfig.direction === "asc" ? 1 : -1;


      return 0;


    });


    return sorted;


  }, [data, sortConfig]);


  const requestSort = (key: string) => {


    let direction: "asc" | "desc" = "asc";


    if (sortConfig && sortConfig.key === key && sortConfig.direction === "asc") {


      direction = "desc";


    }


    setSortConfig({ key, direction });


  };


  return (


    <div className="overflow-x-auto rounded-xl border border-[#1e293b] bg-[#0d1117] p-2">


      <table className="w-full text-left text-sm text-[#c9d1d9] border-collapse">


        <thead>


          <tr className="border-b border-[#1e293b] text-xs uppercase tracking-widest text-[#8b949e]">


            {columns.map(col => (


              <th


                key={col.key}


                onClick={() => col.sortable && requestSort(col.key)}


                className={`py-3 px-4 ${col.sortable ? "cursor-pointer hover:text-[#00d4ff] select-none" : ""}`}


              >


                <div className="flex items-center gap-2">


                  <span>{col.label}</span>


                  {col.sortable && sortConfig?.key === col.key && (


                    <span>{sortConfig.direction === "asc" ? "▲" : "▼"}</span>


                  )}


                </div>


              </th>


            ))}


          </tr>


        </thead>


        <tbody>


          {sortedData.map(item => renderRow(item))}


        </tbody>


      </table>


    </div>


  );


};
